import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.lcm
 */
public class MathUtils_lcm_TriageGen2Test {







    @Test
    public void testLcmPositiveNumbers() {
        // Standard case: lcm(4, 6) = 12
        assertEquals(12, MathUtils.lcm(4, 6));
        // Standard case: lcm(3, 5) = 15
        assertEquals(15, MathUtils.lcm(3, 5));
        // Standard case: lcm(7, 7) = 7
        assertEquals(7, MathUtils.lcm(7, 7));
    }




}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.lcm
 */
public class MathUtils_lcm_TriageGen2Test {









    @Test
    public void testLcmWithNegativeNumbers() {
        // Testing Math.abs() logic: lcm(-4, 6) should be 12
        assertEquals(12, MathUtils.lcm(-4, 6));
        // lcm(4, -6) should be 12
        assertEquals(12, MathUtils.lcm(4, -6));
        // lcm(-4, -6) should be 12
        assertEquals(12, MathUtils.lcm(-4, -6));
    }


}

package org.apache.commons.math.util;

import java.io.*;
