import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.lcm
 */
public class MathUtils_lcm_TriageGen2Test {











    @Test
    public void testLcmLargeNumbers() {
        // Testing larger integers within int range
        // lcm(123, 456) -> gcd is 3. (123/3)*456 = 41 * 456 = 18696
        assertEquals(18696, MathUtils.lcm(123, 456));
    }
}
